package com.ivorama.nlp.transform;
import org.junit.jupiter.api.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class DiscoSettingsTest{
 @Test void freedomIsBoundedAndThresholdsDecreaseContinuously(){double previous=1;for(int n=0;n<=100;n++){var s=new DiscoSettings(true,Path.of("x"),.01,.02,.8,n);assertTrue(s.effectiveRetention()<=previous);assertTrue(s.effectiveRetention()>=.2-1e-12);assertTrue(s.effectiveMargin()>=0);previous=s.effectiveRetention();}assertThrows(IllegalArgumentException.class,()->new DiscoSettings(true,Path.of("x"),.01,.02,.8,101));assertThrows(IllegalArgumentException.class,()->new DiscoSettings(true,Path.of("x"),.01,.02,.8,-1));}
 @Test void freedomLoadsFromYamlWithoutChangingStrictDefault(){assertEquals(0,TransformationConfigLoader.loadLexical(Path.of("src/test/resources/profiles/disco.yml")).disco().semanticFreedom());assertEquals(50,TransformationConfigLoader.loadLexical(Path.of("src/test/resources/profiles/disco-playful.yml")).disco().semanticFreedom());}
 @Test void profileIsExplicitAndNormalDefaultPreserved(){assertFalse(TransformationConfigLoader.loadLexical(Path.of("src/test/resources/profiles/candidate.yml")).disco().enabled());assertTrue(TransformationConfigLoader.loadLexical(Path.of("src/test/resources/profiles/disco.yml")).disco().enabled());}
 @Test void rejectsInvalidThresholds(){assertThrows(IllegalArgumentException.class,()->new DiscoSettings(true,Path.of("x"),Double.NaN,0,.8));assertThrows(IllegalArgumentException.class,()->new DiscoSettings(true,Path.of("x"),.01,-1,.8));assertThrows(IllegalArgumentException.class,()->new DiscoSettings(true,Path.of("x"),.01,.02,2));}
 @Test void syntaxModesCanBeIsolated(){var c=TransformationConfigLoader.load(Path.of("src/test/resources/profiles/disco.yml"));assertTrue(c.replaceNounsEnabled());assertTrue(c.emphaseColores());assertFalse(c.yodaMode());assertFalse(c.joyeuseCirconstanceMode());assertFalse(c.respirationCoolMode());assertFalse(c.stoiquePhiloMode());}
}
